class AlaEServiceUNIProfileProtocolTreatment(TextualConvention, Integer32):
    description = 'The behavior of the bridge in regards to the given protocols packets received on \n        the UNI. Tunnel (1) enables the packets to be tunneled across the provider \n        network.  Discard (2) causes the packets to be discarded and not enter\n        the provider network. Peer (3) means that on this port the bridge is to \n        participate in the protocol. Mac-Tunnel (4) enables mac-tunnelling.'
    status = 'current'
    subtypeSpec = Integer32.subtypeSpec + ConstraintsUnion(SingleValueConstraint(1, 2, 3, 4))
    namedValues = NamedValues(("tunnel", 1), ("drop", 2), ("peer", 3), ("macTunnel", 4))

